/* ═══════════════════════════════════════════════════════════
   SKILL LAB QUESTION BANK
   400 questions: 100 per tool × 4 tools
   Each tool split into Beginner (33), Intermediate (34), Advanced (33)
═══════════════════════════════════════════════════════════ */

export interface QuizQuestion {
  id: number;
  question: string;
  code?: string;
  options: string[];
  answer: number; // 0-indexed
  explanation: string;
  difficulty: 'beginner' | 'intermediate' | 'advanced';
}

export interface NoteSection {
  title: string;
  content: string[];
}

