export const sqlNotes: NoteSection[] = [
  { title:'SQL Fundamentals — SELECT, FROM, WHERE', content:['• SELECT specifies which columns to retrieve.','• FROM identifies the source table(s).','• WHERE filters rows before grouping — cannot contain aggregates.','• Use aliases (AS) for readability: SELECT name AS employee_name FROM staff;','• DISTINCT removes duplicate rows: SELECT DISTINCT city FROM customers;'] },
  { title:'JOINs — Combining Tables', content:['• INNER JOIN: Only matching rows from both tables.','• LEFT JOIN: All left rows + matched right (NULLs if no match).','• RIGHT JOIN: All right rows + matched left.','• FULL OUTER JOIN: All rows from both — NULLs where no match.','• CROSS JOIN: Cartesian product — every row × every row.','• Self-Join: A table joined to itself (e.g., employees to managers).'] },
  { title:'Aggregations & GROUP BY', content:['• Aggregate functions: COUNT(), SUM(), AVG(), MIN(), MAX().','• GROUP BY groups rows with shared values for per-group calculations.','• HAVING filters groups AFTER aggregation (unlike WHERE).','• Example: SELECT dept, COUNT(*) FROM emp GROUP BY dept HAVING COUNT(*) > 5;'] },
  { title:'Window Functions & CTEs', content:['• Window functions: ROW_NUMBER(), RANK(), DENSE_RANK(), LAG(), LEAD(), SUM() OVER().','• PARTITION BY divides results into groups for separate calculations.','• CTE: WITH name AS (SELECT ...) SELECT * FROM name;','• Recursive CTEs traverse hierarchical data (org charts, trees).'] },
];

